local W, H = grid_size_x(), grid_size_y()

-- ---- state ----
local state = {
  mutes_count = 0,
}

-- ---- region: mutes ----
local function handle_mutes(x, y, z)
  if z == 1 then
    state.mutes_count = state.mutes_count + 1
    if state.mutes_count == 1 then
      midi_cc(100, 127, 1)
    end
  else
    state.mutes_count = state.mutes_count - 1
    if state.mutes_count == 0 then
      midi_cc(100, 0, 1)
    end
  end
end

-- ---- LED draw ----
local function redraw()
  grid_led_all(0)
  -- region: mutes
  do
    local lit = state.mutes_count > 0 and 12 or 3
    grid_led(0, 0, lit)
    grid_led(1, 0, lit)
    grid_led(2, 0, lit)
    grid_led(3, 0, lit)
    grid_led(4, 0, lit)
    grid_led(5, 0, lit)
    grid_led(6, 0, lit)
    grid_led(7, 0, lit)
  end
  grid_refresh()
end

-- ---- dispatch ----
local _route = {}
_route[0 + 0*W] = handle_mutes
_route[1 + 0*W] = handle_mutes
_route[2 + 0*W] = handle_mutes
_route[3 + 0*W] = handle_mutes
_route[4 + 0*W] = handle_mutes
_route[5 + 0*W] = handle_mutes
_route[6 + 0*W] = handle_mutes
_route[7 + 0*W] = handle_mutes

function event_grid(x, y, z)
  local h = _route[x + y*W]
  if h then h(x, y, z) end
  redraw()
end

-- ---- init ----
redraw()
